try {
  const data = $input.filter(item => {
    return !item.json.summary || item.json.summary.trim() === '';
  });
  if (data.length === 0) {
    return [{ json: { _no_new_jobs: true } }];
  }
  return data.slice(0, 5);
} catch(e) {
  return [{ json: { _error: e.message } }];
}

// ── Build prompt from job data ──────────────────────────────────────────
const job = $json;
const prompt = `Extract structured data from this job posting. Return ONLY valid JSON, no other text.

Title: ${job.title}
Company: ${job.company}
Description: ${(job.description || '').substring(0, 3000)}

{
  "required_years_experience": <number>,
  "required_skills": ["skill1", "skill2"],
  "preferred_skills": ["skill1", "skill2"],
  "education_required": "<degree or ''>",
  "seniority": "<junior|mid|senior|staff|lead|not specified>",
  "is_remote": <true|false>,
  "remote_policy": "<fully_remote|hybrid|on_site|not_specified>",
  "has_visa_sponsorship": <true|false>,
  "benefits": ["benefit1", "benefit2"],
  "industry": "<industry>",
  "summary": "<brief 2-sentence summary>"
}`;

// ── Call Ollama (free local LLM) ──────────────────────────────────────
try {
  const response = await fetch('http://localhost:11434/api/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'llama3.2',
      stream: false,
      messages: [{ role: 'user', content: prompt }]
    })
  });

  if (!response.ok) {
    throw new Error(`Ollama returned ${response.status}`);
  }

  const data = await response.json();
  const rawContent = data?.message?.content || data?.response || '{}';

  // ── Parse JSON from Ollama response ────────────────────────────────
  let extracted = {};
  try {
    extracted = JSON.parse(rawContent);
  } catch {
    const match = rawContent.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (match) {
      try { extracted = JSON.parse(match[1]); } catch {}
    }
  }

  return {
    json: {
      source_id: job.source_id,
      source: job.source,
      title: job.title,
      company: job.company,
      location: job.location,
      country: job.country,
      salary_min: job.salary_min,
      salary_max: job.salary_max,
      currency: job.currency,
      description: job.description,
      application_url: job.application_url,
      posted_at: job.posted_at,
      required_years_experience: extracted.required_years_experience ?? 0,
      required_skills: (extracted.required_skills || []).join(', '),
      preferred_skills: (extracted.preferred_skills || []).join(', '),
      education_required: extracted.education_required || '',
      seniority: extracted.seniority || 'not specified',
      is_remote: extracted.is_remote ?? false,
      remote_policy: extracted.remote_policy || 'not_specified',
      has_visa_sponsorship: extracted.has_visa_sponsorship ?? false,
      benefits: (extracted.benefits || []).join(', '),
      industry: extracted.industry || '',
      summary: extracted.summary || ''
    }
  };

} catch(e) {
  // ── Fallback: pass through job data with empty enrichment ───────────
  return {
    json: {
      source_id: job.source_id,
      source: job.source,
      title: job.title,
      company: job.company,
      location: job.location,
      country: job.country,
      salary_min: job.salary_min,
      salary_max: job.salary_max,
      currency: job.currency,
      description: job.description,
      application_url: job.application_url,
      posted_at: job.posted_at,
      required_years_experience: 0,
      required_skills: '',
      preferred_skills: '',
      education_required: '',
      seniority: 'not specified',
      is_remote: false,
      remote_policy: 'not_specified',
      has_visa_sponsorship: false,
      benefits: '',
      industry: '',
      summary: '',
      _enrich_error: e.message
    }
  };
}
